    seleccion: ['ATHLETIX está dirigido a operación estructural cuando el comité prioriza un ajuste próximo al cuerpo y menor volumen bajo el equipo autónomo. Su diferencia frente al G-XTREME 3.0 es el sistema de paneles elásticos y el shell PBI Stretch XT con Kevlar; frente al CLASSIX, abandona el hombro caído por una construcción atlética con codos articulados. La banda telescópica con doble puño y el fit Women’s son puntos de revisión propios de este modelo.', 'Para pedir ATHLETIX, identifique PBI Stretch XT, el acabado FreeFAS y la barrera CROSSTECH Innovate sólo cuando sean los materiales seleccionados. Solicite chaquetón y pantalón compatibles, talla Women’s cuando corresponda y el tipo de espalda extendida si se requiere. Los colores, combinación de capas, ribetes y letras institucionales deben quedar en la orden de configuración, no inferirse del nombre ATHLETIX.'],
    idealPara: ['Trabajo con SCBA donde se desea menor volumen frontal', 'Ascenso, gateo y alcances que requieren codos articulados', 'Corporaciones que deben evaluar ajuste Women’s', 'Pruebas comparativas de movilidad con paneles elásticos'],
    aConsiderar: ['ATHLETIX se publica para aplicación estructural, no para proximidad.', 'El shell y su acabado no sustituyen identificar barrera y forro térmico en la orden.', 'Defina los materiales y colores disponibles antes de emitir la requisición.'],
