    faqs: [{ q: '¿Qué diferencia ATHLETIX de los otros Globe?', a: 'Su patrón atlético usa paneles elásticos, codos articulados y PBI Stretch XT con Kevlar para reducir volumen.' }, { q: '¿ATHLETIX admite fit Women’s?', a: 'Sí, MSA publica fit Women’s; solicite tallas y largos por separado para chaquetón y pantalón.' }, { q: '¿Qué acabado recibe PBI Stretch XT?', a: 'MSA indica FreeFAS, un acabado repelente duradero sin PFAS añadidos intencionalmente.' }],
