    seleccion: ['Defender es el conjunto Sköld para brigadas industriales de primera respuesta, con shell Nomex IIIA, barrera de neopreno, manga Kevlar y cierre de escape. No debe equipararse a Herö para una compra que exige certificación de tercero: el fabricante declara equivalencia con NFPA 1971 edición 1991. Su ventaja operativa es la venta por componentes: chaquetón FPJ01, pantalón FPP01, tirantes FPT01 o kit FPKIT.', 'La requisición debe identificar si se adquiere FPKIT o piezas de reposición y precisar que se requiere la declaración de equivalencia del fabricante. Defina bandas reflejantes, tirantes, opción de DRD y tallaje de cada prenda. Para una brigada industrial, valide que el riesgo de la planta coincide con el alcance de esta configuración; si el pliego demanda certificación independiente, seleccione un conjunto que la documente expresamente.'],
