    aConsiderar: ['Es una equivalencia declarada por fabricante, no certificación de laboratorio acreditado.', 'No sustituye a Herö cuando el pliego exige certificación de tercero.', 'Solicite declaración escrita de equivalencia y composición de las capas contratadas.'],
    incluye: ['FPKIT: chaquetón, pantalón y tirantes', 'FPJ01 chaquetón', 'FPP01 pantalón', 'FPT01 tirantes'],
