    seleccion: ['El Overol de Rescate Sköld es una prenda FR de una pieza para tareas técnicas, con costuras de Kevlar, cierre con solapa de broches, bolsillo de radio, bolsas cargo y presillas para lámpara y micrófono. Frente a Herö y Defender no es un turnout estructural: la certificación NFPA 2112 publicada corresponde a la tela ignífuga y al reflejante antiflama. Su valor de selección está en la configuración de color, identificación y distribución de bolsillos para la cuadrilla.', 'Defina repelente al agua si se requiere, color de la prenda, reflejante plata o amarillo lima y ancho de 1, 2 o 3 pulgadas. Solicite bordado o impresión como partida adicional y confirme que no afecte el alcance de la prenda. Para ataque interior, proximidad o exposición química, seleccione el EPP específico; el overol no debe presentarse como sustituto de un conjunto NFPA 1970.'],
