    specs: { norma: 'Industrial; no certificada NFPA para bomberos', resolucion: '640×480 px', netd: '<50/<40/<30 mK a 30 °C según lente', rango_temp: '−20 a 120 °C; 0 a 650 °C; 300 a 1,500 °C', pantalla: 'LCD táctil IPS de 4 pulgadas, 640×480 px, con rotación', autonomia: 'Aprox. 4 h', peso: '1.4 kg con batería' },
    seleccion: ['La T560 pertenece a inspección profesional, no a una línea de cámaras para ataque estructural. Su valor está en convertir una lectura térmica en dato de mantenimiento: mide en tres rangos hasta 1,500 °C, usa una resolución IR de 640×480 px y permite seleccionar lentes de 14°, 24°, 42° u 80°. La sensibilidad cambia con el lente; FLIR publica desde menos de 30 mK a 30 °C para 42° hasta menos de 50 mK para 14° y 80°.', 'La plataforma giratoria de 180° y la pantalla táctil IPS de cuatro pulgadas simplifican inspecciones sobre tableros, motores o puntos elevados desde posiciones incómodas. Incluye cámara visual de 5 MP, tarjeta SD removible y opciones de transmisión de video radiométrico por UVC; por eso se diferencia de K75 y K85-N, concebidas para observación en incendio. Con 1.4 kg y autonomía aproximada de cuatro horas, la T560 exige planear lente, distancia y emisividad de cada activo antes de comparar tendencias térmicas. UltraMax procesa cuatro veces más píxeles después de capturar la imagen.'],
    idealPara: ['Inspección de tableros eléctricos y componentes mecánicos', 'Rondas que necesitan datos radiométricos y tarjeta SD', 'Medición industrial por encima de 650 °C', 'Diagnóstico en sitios con acceso visual limitado'],
    aConsiderar: ['No se debe presentar como cámara certificada para combate de incendios.', 'El NETD, campo de visión y distancia mínima dependen del lente contratado.', 'La temperatura indicada requiere ajustar emisividad y demás correcciones de medición.'],
    incluye: ['Cámara con lente según variante', 'Dos baterías y cargador', 'Estuche rígido, correas, tapa frontal y tarjeta SD de 8 GB', 'Cables USB y documentación'],
    faqs: [{ q: '¿La T560 está diseñada para ataque interior?', a: 'No. FLIR la clasifica como cámara térmica profesional para inspección, no como TIC certificada NFPA para bomberos.' }, { q: '¿Cuál es el máximo rango de medición?', a: 'El tercer rango publicado cubre de 300 a 1,500 °C.' }, { q: '¿La pantalla cambia de orientación?', a: 'Sí. FLIR publica una pantalla táctil de 4 pulgadas con rotación automática y plataforma de lente giratoria.' }],
    fuentes: [{ titulo: 'FLIR — T560', url: 'https://www.flir.com/es-es/products/t560/' }],
