    faqs: [{ q: '¿Qué apertura publica PSP50?', a: 'Holmatro indica 725 mm de distancia de separación.' }, { q: '¿Cuál es la fuerza máxima del PSP50?', a: 'La ficha técnica publica 366 kN de fuerza máxima de separación.' }, { q: '¿Comparte batería con las demás Pentheon?', a: 'La plataforma usa batería PBPA288, que Holmatro identifica para sus herramientas Pentheon.' }],
    fuentes: [{ titulo: 'Holmatro — Separador PSP50', url: 'https://www.holmatro.com/es/rescate/separador-psp50/' }, { titulo: 'Holmatro — herramientas Pentheon', url: 'https://www.holmatro.com/es/rescate/bomberos-y-rescate/herramientas-pentheon/' }],
