    specs: { norma: 'EN 13204:2025 · NFPA 1960', clasificacion: 'EN: F-CT3-43/380-J; NFPA: A7 B8 C8 D8 E8 F3', fuerza: 'Separación máxima: 1,860 kN', rango: 'Separación 380 mm; apertura de corte 320 mm', fuente: 'Batería PBPA288', peso: '20.5 kg lista para uso', extra: 'IP57; Bluetooth; puntas desmontables' },
    seleccion: ['PCT50 integra corte, separación, compresión y tracción en una herramienta de 20.5 kg lista para uso. Ofrece 380 mm de separación, 320 mm de apertura de corte y 254 mm de tracción, de modo que permite resolver varias maniobras antes de pedir un cambio de herramienta. La clasificación F-CT3-43/380-J bajo EN 13204:2025 y A7 B8 C8 D8 E8 F3 bajo NFPA 1960 facilita comparar su capacidad publicada con otra combinada, sin atribuirle la capacidad de una cizalla dedicada.', 'La herramienta alcanza 1,860 kN de fuerza máxima de separación y usa PBPA288. Sus puntas desmontables permiten cortar material sin destrozarlo, según Holmatro, y la carcasa se publica IP57. Frente a PSP50 y PCU50, PCT50 reduce el número de equipos que debe trasladar la primera dotación, pero no conserva la apertura de 725 mm del separador ni los 182 mm de la cizalla. La orden debe indicar el modelo 151.002.421, batería, cargador y el conjunto de tracción si se requiere. El control en línea de dos velocidades mantiene mando preciso con carga variable.'],
