    seleccion: ['Dock 2 no es una aeronave ni una cámara: es una estación de 34 kg sin aeronave, diseñada para alojar una Matrice 3D o 3TD y automatizar despliegues planificados. DJI publica IP55 para el dock e IP54 para la aeronave, un radio máximo de operación de 10 km y capacidad para una unidad. La Matrice 3TD aporta la carga térmica dentro de esa combinación; por eso no debe anunciarse que la estación, por sí sola, incorpora un sensor térmico.', 'La estación carga la aeronave apagada de 20 a 90 % en 32 minutos a 25 °C. DJI reporta hasta 50 minutos de vuelo para Matrice 3D en condiciones controladas, aunque el alcance de misión se calcula reservando batería y considera viento, velocidad y tiempo de permanencia. Frente a M30T o Mavic 3T, la ventaja no es la portabilidad sino la continuidad de una operación con sitio, energía, red, mantenimiento y procedimientos de contingencia definidos. FlightHub 2 y Cloud API pueden formar parte de la integración, pero deben solicitarse y configurarse conforme a la arquitectura de datos de la institución.'],
