    seleccion: ['TK613T es la referencia Tychem 10000 que DuPont publica como encapsulado de entrada frontal. Su barrera combina películas multicapa laminadas a ambos lados de un sustrato de poliéster; el cierre gas-tight, el visor amplio y los calcetines integrados forman parte del conjunto. Frente a Tychem 6000 FR, que es una prenda no encapsulada, este modelo se elige cuando el análisis de riesgo exige una envolvente de vapor y líquido.', 'La etiqueta NFPA 1990 (1994 Clase 2) corresponde a TK613T, no al nombre Tychem 10000 en abstracto. Para una requisición trazable, pida esa referencia, talla y el conjunto de guantes o botas compatible. La compatibilidad química depende de sustancia, concentración, fase, tiempo y demás componentes del traje; compare la tabla de permeación de DuPont antes de autorizar una entrada.'],
    idealPara: ['Respuesta HAZMAT con riesgo de vapor y líquido', 'Equipos que requieren una prenda completamente encapsulada', 'Compras que pueden especificar TK613T por número de parte'],
