    incluye: ['Traje encapsulado TK613T con visor, cierre gas-tight y calcetines integrados'],
    faqs: [{ q: '¿Qué referencia Tychem 10000 se documenta en esta ficha?', a: 'TK613T, un encapsulado de entrada frontal publicado por DuPont.' }, { q: '¿Por qué no se compara como un overol Tychem 6000 FR?', a: 'TK613T es encapsulado; Tychem 6000 FR se publica como prenda no encapsulada.' }, { q: '¿La barrera confirma compatibilidad con cualquier sustancia?', a: 'No. Revise la tabla de permeación del fabricante para el químico, concentración y condición de exposición.' }],
    fuentes: [{ titulo: 'DuPont — Tychem 10000 TK613T', url: 'https://www.dupont.com/content/dupont/apac/ap/en/products/personal-protection/safespec/tychem-10000-tk613t-ly.html' }],
