    norm: 'NFPA 1990 (1992) · TP198T/TP199T',
    specs: { norma: 'NFPA 1990 (1992) · TP198T/TP199T; NFPA 70E HRC 2', nivel_haz: 'Prenda no encapsulada para salpicadura', barrera: 'Tychem 6000 FR', configuracion: 'Overol con capucha, costuras cosidas y cubiertas', extra: 'Doble solapa autoadherible en el cierre' },
    seleccion: ['Tychem 6000 FR resuelve exposición por salpicadura con un overol no encapsulado; esa diferencia evita confundirlo con TK613T. DuPont identifica TP198T y TP199T con NFPA 1990 (1992) y NFPA 70E HRC 2. La capucha, las costuras cosidas y cubiertas, y la doble solapa hacen que el cierre sea una parte específica de la configuración, no un accesorio intercambiable de la familia.', 'Seleccione TP198T o TP199T en la orden y confirme su etiquetado. La condición HRC 2 no convierte el overol en protección para una exposición de vapor ni sustituye la ropa o sistema de protección que demande la evaluación eléctrica. Para el químico de trabajo, coteje material, costuras y cierre con los datos de DuPont antes de fijar tiempo de tarea, guante y protección respiratoria.'],
    idealPara: ['Salpicadura química con prenda no encapsulada', 'Órdenes que requieren TP198T o TP199T identificados', 'Evaluaciones donde también se revisa la condición NFPA 70E HRC 2'],
    aConsiderar: ['No utilice un overol no encapsulado donde el peligro evaluado exige protección contra vapor.', 'Verifique que TP198T o TP199T aparezca en etiqueta y documento de suministro.', 'Defina el sistema completo de EPP; el overol no determina por sí solo la protección eléctrica.'],
    incluye: ['Overol Tychem 6000 FR con capucha y cierre de doble solapa'],
    faqs: [{ q: '¿Qué modelos tienen la referencia NFPA indicada?', a: 'TP198T y TP199T son los modelos citados para NFPA 1990 (1992).' }, { q: '¿Tychem 6000 FR es un encapsulado?', a: 'No; esta ficha corresponde a un overol no encapsulado.' }, { q: '¿La condición HRC 2 cubre cualquier riesgo térmico?', a: 'No. Debe confirmarse dentro de la evaluación eléctrica y de la configuración completa de EPP.' }],
    fuentes: [{ titulo: 'DuPont — Tychem 6000 TF198T', url: 'https://www.dupont.com/content/dupont/apac/ap/en/products/personal-protection/safespec/tychem-6000-model-tf198t-gy.html' }],
