const enriquecimientoR11bRescate: Record<string, Partial<Product>> = {
  'petzl-astro-bod-fast': { seleccion: ['ASTRO BOD FAST es el arnés de Petzl para operaciones de acceso por cuerda donde el operador necesita progresar con el bloqueador CROLL L integrado y conectar equipo compatible en el punto ventral abrible. Frente a una camilla, una polea o un descensor de esta misma categoría, es el componente que permanece puesto en el rescatista y organiza la sujeción, el posicionamiento y el ascenso; no reemplaza la selección del sistema de descenso ni del anclaje. Sus certificaciones publicadas cubren detención de caídas, posicionamiento, asiento y el uso del CROLL L como dispositivo tipo B.', 'Al cotizarlo, pida la talla y versión exactas, y confirme que los conectores, el descensor y los elementos conectados al punto ventral sean compatibles con la configuración planeada. La compra debe incluir la revisión de ajuste con el usuario, porque una talla correcta y el cierre de las hebillas forman parte del uso previsto. Antes de cada asignación inspeccione cintas, costuras, puntos de conexión, CROLL L y hebillas FAST; retire el arnés de servicio para evaluación si observa daño, contaminación o funcionamiento irregular. El manual de Petzl y el programa de inspección del equipo deben definir limpieza, registro y criterio de retiro.'], idealPara: ['Es adecuado para un técnico que realizará acceso por cuerda con ascenso mediante CROLL L.', 'Puede integrarse en una maniobra que requiera posicionamiento y un punto ventral abrible.', 'Sirve cuando el equipo de rescate necesita separar arnés, descensor y sistema de izado.'], aConsiderar: ['Si la maniobra requiere detención de caídas, confirme que la conexión usada corresponda al punto autorizado.', 'Antes de pedirlo, compruebe talla, versión y compatibilidad de cada componente conectado al punto ventral.', 'No asigne un arnés con cintas cortadas, costuras dañadas o hebillas que no cierren correctamente.'], faqs: [{ q: '¿Qué bloqueador incorpora este arnés?', a: 'Petzl publica un CROLL L integrado para la progresión por cuerda.' }, { q: '¿Qué permite el punto ventral?', a: 'Permite conectar equipo compatible en una configuración de acceso por cuerda.' }, { q: '¿Sustituye a un descensor?', a: 'No. El descensor se selecciona y configura como componente independiente del sistema.' }] },
  'petzl-maestro-s': { seleccion: ['MAESTRO S es el descensor con función de izado que Petzl destina al rescate técnico con cuerda de 10.5 a 11.5 mm. A diferencia de RESCUE S, que es una polea compacta, este equipo controla el descenso y permite pasar a una maniobra de izado sin sustituir el dispositivo. Frente al MPD de CMC, el comprador debe evaluar la cuerda nominal publicada para cada modelo y el procedimiento que domina su personal, en vez de tratarlos como equivalentes intercambiables. Petzl publica una carga de trabajo de hasta 250 kg para este MAESTRO S y compatibilidad con sus cuerdas especificadas.', 'La solicitud debe indicar diámetro, construcción y condición de la cuerda que utilizará la cuadrilla, además de conectores, anclajes y aparejo previstos. Pida capacitación y el manual operativo del modelo con la entrega, ya que el control de descenso depende de instalar y operar el dispositivo conforme a sus instrucciones. Revise el recorrido de cuerda, la placa móvil, la leva, el mango y los puntos de conexión antes de usarlo; después de una carga anormal, contaminación o caída, aplique el criterio de evaluación publicado. Mantenga el equipo limpio y registrado, y no mezcle diámetros fuera del intervalo declarado sólo porque una cuerda parezca entrar físicamente.'], idealPara: ['Es adecuado para rescate técnico que emplea cuerda dentro del rango de 10.5 a 11.5 mm.', 'Puede usarse en un sistema que deba convertir una operación de descenso en una de izado.', 'Sirve para cuadrillas que requieren un descensor dedicado distinto de una polea compacta.'], aConsiderar: ['Si la cuerda propuesta queda fuera del intervalo publicado, no la especifique para este descensor.', 'Pida que el procedimiento de cambio a izado sea compatible con la capacitación de la cuadrilla.', 'Antes de cada uso, inspeccione leva, mango, placas y recorrido de la cuerda conforme al manual.'], faqs: [{ q: '¿Qué rango de cuerda publica Petzl?', a: 'Petzl publica uso con cuerda de 10.5 a 11.5 mm.' }, { q: '¿Cuál es la carga de trabajo publicada?', a: 'La ficha del modelo publica una carga de trabajo de hasta 250 kg.' }, { q: '¿Es una polea compacta?', a: 'No. Es un descensor con función de izado para rescate técnico.' }] },
  'petzl-rescue-s': { seleccion: ['RESCUE S es una polea compacta de alto rendimiento para integrar polipastos y sistemas de rescate en altura con cuerdas de 6 a 11 mm. Su roldana de 25 mm con rodamiento sellado y las placas laterales móviles la distinguen como un componente de reenvío; no controla por sí sola el descenso como MAESTRO S ni reúne las funciones de belay y descenso del MPD. Petzl publica rendimiento de 91 %, carga de trabajo de 5 kN y resistencia de 18 kN, datos que deben incorporarse al cálculo y al diseño de la maniobra, no copiarse como capacidad de todo el sistema.', 'Al comprar, confirme diámetro de cuerda, conectores y anclaje, además del espacio que tendrá el polipasto armado. Verifique que la selección de conectores permita cerrar las placas sin carga lateral o interferencia; el peso de 52 g no elimina la necesidad de compatibilidad entre todos los componentes. Antes de cada uso, revise la roldana, las placas, el eje y el libre giro; después de contacto con suciedad, agua contaminada o golpes, limpie y evalúe el equipo conforme a las instrucciones de Petzl. No continúe usando una polea con desgaste, bordes dañados o funcionamiento áspero, y conserve el historial de inspección dentro del programa de rescate.'], idealPara: ['Es adecuada para un polipasto compacto con cuerda de 6 a 11 mm.', 'Puede integrarse en rescate en altura cuando se requiere una polea con placas móviles.', 'Sirve para un sistema cuya carga de trabajo se haya calculado sin exceder 5 kN.'], aConsiderar: ['Si el sistema exige control de descenso, seleccione además un dispositivo diseñado para esa función.', 'Antes de montar el polipasto, confirme que la carga prevista y los conectores sean compatibles con la polea.', 'Retire de uso la unidad si la roldana no gira libremente o presenta desgaste visible.'], faqs: [{ q: '¿Qué eficiencia publica la ficha?', a: 'Petzl publica un rendimiento de 91 % para RESCUE S.' }, { q: '¿Qué cuerdas admite?', a: 'La especificación publicada indica cuerdas de 6 a 11 mm.' }, { q: '¿Cuál es su carga de trabajo?', a: 'La carga de trabajo publicada es de 5 kN.' }] },
  'cmc-mpd-13mm': { seleccion: ['MPD 333000 es el dispositivo CMC para rescate con cuerda de 12.5 a 13 mm que integra polea, control de descenso y belay en una misma unidad. Esa integración lo diferencia de la RESCUE S de Petzl, que sólo aporta reenvío, y del MAESTRO S, cuyo rango de cuerda publicado es distinto. CMC publica para esta versión una carga máxima de 272 kg y resistencia de polea de 46 kN. El modelo de 13 mm debe identificarse explícitamente en la compra, porque la versión para 11 mm no se selecciona sólo por nombre comercial o por apariencia.', 'La cotización debe incluir diámetro y tipo de cuerda, aplicación de línea principal o belay, conectores y método de anclaje que usará el equipo. Solicite el manual y capacitación de aparejo, en especial si la cuadrilla pretende pasar de descenso a izado sin desarmar la maniobra. Antes de colocar el MPD, inspeccione leva, liberador, placas, polea, puntos de conexión y recorrido de la cuerda; compruebe además que la cuerda no esté contaminada, aplastada ni fuera del rango publicado. Después de una carga excepcional o una falla de operación, retire el dispositivo para revisión conforme al fabricante. Mantenga registro de inspecciones y no sustituya el procedimiento operativo por la sola presencia del bloqueo.'], idealPara: ['Es adecuado para rescate con cuerda de 12.5 a 13 mm y una carga planificada.', 'Puede emplearse en una configuración que combine línea principal, belay y cambio a izado.', 'Sirve para espacios confinados cuando el aparejo y la capacitación ya están definidos.'], aConsiderar: ['Si el proyecto usa cuerda de 11 mm, no solicite esta versión sin confirmar el modelo correspondiente.', 'Antes de usarlo, revise leva, liberador y polea siguiendo el manual de CMC.', 'No interprete la carga máxima publicada como autorización para omitir cálculo de anclajes y sistema completo.'], faqs: [{ q: '¿Qué funciones reúne el MPD?', a: 'CMC publica polea, control de descenso y belay en el mismo dispositivo.' }, { q: '¿Qué diámetro de cuerda corresponde a esta versión?', a: 'Esta referencia está publicada para cuerda de 12.5 a 13 mm.' }, { q: '¿Cuál es la carga máxima indicada?', a: 'CMC publica una carga máxima de 272 kg.' }] },
  'cmc-titanium-split-apart-litter': { seleccion: ['Titanium Split-Apart es la camilla canastilla de CMC construida con titanio y red Durathene, diseñada para separarse en dos secciones cuando el transporte y almacenamiento requieren esa configuración. Se diferencia de la Model 71 de Ferno porque CMC publica una camilla desmontable, puntos StratLoad y cuatro correas, mientras que la elección de una canastilla no sustituye el empaque del paciente ni el bridle compatible. La ficha publica 7.5 kg, dimensiones de 212 × 60 × 19 cm y límite de carga de 11 kN; esas cifras deben revisarse junto con el sistema completo de izado y sus conectores.', 'Pida el conjunto exacto de secciones, correas, bridle y accesorios de inmovilización que requiere el protocolo. Antes de comprar, confirme que el vehículo, el área de operación y la ruta de traslado admitan sus dimensiones; una canastilla ligera no resuelve por sí misma una extracción compleja. En cada uso inspeccione el cierre entre secciones, rieles, red, puntos StratLoad y correas, y compruebe el empaque del paciente antes de mover o elevar. Después de un golpe, una carga inusual o daño en red y rieles, suspenda servicio para evaluación. El mantenimiento debe seguir las instrucciones de CMC y documentar cualquier pieza reemplazada.'], idealPara: ['Es adecuada para trasladar un paciente cuando se requiere una canastilla que se desarma en dos secciones.', 'Puede integrarse en una maniobra con bridle compatible y puntos StratLoad inspeccionados.', 'Sirve para equipos que necesitan revisar dimensiones y peso antes de definir su almacenamiento.'], aConsiderar: ['Si el paciente será elevado, valide bridle, anclajes y empaque como un sistema completo.', 'Antes de cada operación, confirme que las dos secciones queden cerradas y aseguradas correctamente.', 'Retire la camilla para evaluación si los rieles, la red o las correas presentan daño.'], faqs: [{ q: '¿De qué material está fabricada?', a: 'CMC publica una estructura de titanio y una red Durathene.' }, { q: '¿Qué límite de carga publica?', a: 'La ficha técnica publica un límite de carga de 11 kN.' }, { q: '¿La camilla se desmonta?', a: 'Sí. El modelo se configura en dos secciones separables.' }] },
  'ferno-model-71': { seleccion: ['Model 71 es la camilla canastilla de Ferno con carcasa de polietileno de alta densidad y bastidor de aluminio para proteger al paciente durante transporte sobre terreno irregular. Frente a la Titanium Split-Apart de CMC, no se describe como una camilla desmontable de titanio; su decisión de compra debe partir de la forma completa, el espacio de estiba y los accesorios que Ferno publica para este modelo. La capacidad publicada es de 600 lb, con dimensiones de 86 × 24 × 8 pulgadas y peso de 23 lb. Incluye cuatro restricciones de paciente, asas moldeadas y colchón reemplazable, pero esos elementos no reemplazan la inmovilización que determine el protocolo médico.', 'Solicite por separado el bridle compatible, líneas de guía, collar de flotación opcional y cualquier accesorio necesario para la misión. Antes de ponerla en servicio, confirme que la configuración adquirida corresponde a traslado terrestre, elevación planificada o ambiente acuático, sin asumir que un accesorio opcional viene incluido. Inspeccione carcasa, bastidor, asas, restricciones y colchón antes de cada salida; revise también que no existan grietas, deformaciones o uniones flojas. Después de impacto, sobrecarga o contaminación, retire la camilla hasta que el programa de mantenimiento determine su condición. La elevación debe conservar líneas de guía y aparejo compatible, con personal capacitado para controlar el movimiento.'], idealPara: ['Es adecuada para traslado de paciente sobre terreno irregular con una canastilla de carcasa rígida.', 'Puede emplearse en una operación que requiera cuatro restricciones de paciente y asas moldeadas.', 'Sirve para equipos que definirán por separado bridle, líneas de guía y accesorios opcionales.'], aConsiderar: ['Si la operación incluye elevación, pida el bridle compatible y el método de control de carga.', 'No suponga que el collar de flotación opcional forma parte de la entrega estándar.', 'Antes de cada uso, inspeccione carcasa, bastidor y restricciones de paciente por daños o deformación.'], faqs: [{ q: '¿Cuál es el límite de carga publicado?', a: 'Ferno publica un límite de carga de 600 lb para Model 71.' }, { q: '¿Qué estructura utiliza?', a: 'El modelo combina carcasa de HDPE con bastidor de aluminio.' }, { q: '¿Incluye restricciones para el paciente?', a: 'La ficha publica cuatro restricciones de paciente.' }] },
};

const enriquecimientoR11bForestal: Record<string, Partial<Product>> = {
  'council-tool-mcleod-mt48': { seleccion: ['MT48 FSS es la herramienta McLeod de Council Tool que combina rastrillo y azadón en una cabeza de acero alto carbono con mango de fresno de 48 pulgadas. Se diferencia de la Pulaski porque privilegia retirar combustible superficial y trabajar suelo sin incorporar una hoja de hacha; frente al rastrillo LW12-60, añade una superficie de azadón para intervenir la línea. Council Tool publica construcción tratada térmicamente, peso de 5 lb y especificación USDA Forest Service 5100-353D. Es una herramienta manual para construcción de línea, no un sustituto de una bomba de mochila ni de la evaluación del comportamiento del fuego.', 'Al comprar, confirme la clave MT48 FSS, longitud de mango y el tipo de trabajo predominante de la brigada. La compra debe considerar funda, transporte seguro y el EPP forestal seleccionado para la operación; la herramienta no define por sí sola la protección térmica del usuario. Antes de cada jornada revise que la cabeza esté firme, que el mango no tenga grietas y que el filo no presente daño que afecte el control. Retire de servicio una unidad floja o agrietada y mantenga la distancia de trabajo con otros operadores. La limpieza posterior debe quitar tierra y residuos sin alterar el mango ni la unión, conforme al programa interno de mantenimiento.'], idealPara: ['Es adecuada para una cuadrilla que retirará combustible superficial al construir una línea de control.', 'Puede utilizarse cuando el trabajo requiere rastrillar y mover suelo con una sola herramienta.', 'Sirve para operaciones que prefieren una McLeod distinta de una Pulaski con hoja de hacha.'], aConsiderar: ['Antes de pedirla, confirme que el mango de 48 pulgadas corresponde al alcance requerido por la cuadrilla.', 'No use una herramienta cuya cabeza esté floja o cuyo mango muestre grietas.', 'Durante la operación, conserve separación suficiente para evitar contacto con la herramienta de otro brigadista.'], faqs: [{ q: '¿Qué funciones combina la MT48 FSS?', a: 'Council Tool la publica como rastrillo y azadón para trabajo de línea.' }, { q: '¿Qué peso tiene publicado?', a: 'La ficha del modelo publica un peso de 5 lb.' }, { q: '¿Qué especificación USDA indica?', a: 'Council Tool indica USDA Forest Service 5100-353D.' }] },
  'council-tool-pulaski-38pe136-nfes': { seleccion: ['Pulaski 38PE136 NFES es la herramienta Council Tool con hoja de hacha y azadón, destinada a corte, excavación y desbroce durante trabajo forestal. Se distingue de la McLeod MT48 porque incorpora un filo de hacha para vegetación y no un rastrillo; tampoco tiene la función de remate con caucho del FS15. Council Tool publica cabeza de 3.75 lb en acero 1080 forjado, mango de nogal de 36 pulgadas y conformidad USFS 5100-355E. El filo afilado a mano exige que el comprador trate esta referencia como herramienta de corte y planee su transporte y separación operativa.', 'Al cotizar, solicite la referencia 38PE136 NFES y confirme que la longitud de 36 pulgadas se adapta al procedimiento de la brigada. Defina funda de filo, almacenamiento y reemplazo de mango antes de asignarla; no convierta una herramienta de corte en un equipo de uso indistinto. Inspeccione unión de cabeza y mango, condición del azadón y borde de la hoja antes de cada jornada. Si hay holgura, mango rajado o deformación, retire la Pulaski hasta corregirla mediante el proceso autorizado. Use EPP adecuado y mantenga una zona de trabajo libre de personas dentro del arco de movimiento.'], idealPara: ['Es adecuada para cortar vegetación y excavar en una línea forestal con la misma herramienta.', 'Puede emplearse cuando la cuadrilla requiere una hoja de hacha y un azadón en un mango de 36 pulgadas.', 'Sirve para desbroce manual donde una McLeod no aporta capacidad de corte equivalente.'], aConsiderar: ['Si el traslado se realiza junto a personal, proteja el filo y asegure la herramienta.', 'Antes de usarla, revise que la cabeza no tenga holgura sobre el mango de nogal.', 'No balancee la Pulaski sin establecer distancia segura con los demás operadores.'], faqs: [{ q: '¿Qué acero publica Council Tool?', a: 'La cabeza está publicada en acero 1080 forjado.' }, { q: '¿Qué longitud tiene el mango?', a: 'Council Tool publica un mango de nogal de 36 pulgadas.' }, { q: '¿Qué especificación USFS indica?', a: 'La ficha del modelo indica USFS 5100-355E.' }] },
  'council-tool-fire-rake-lw12-60': { seleccion: ['LW12-60 es el rastrillo forestal Council Tool con cuatro dientes triangulares de acero y mango de fresno de 60 pulgadas. Está orientado a rastrillar, cortar y mover sotobosque durante la construcción de líneas de fuego. A diferencia de MT48 FSS, no integra una superficie de azadón; frente a la Pulaski, no incorpora un filo de hacha. Esa diferencia permite comprarlo para trabajo repetido sobre combustible ligero cuando el procedimiento no requiere cortar con hoja. Council Tool publica dientes endurecidos, mango desmontable y especificación USDA Forest Service 5100-284C.', 'Al adquirirlo, confirme que se solicita LW12-60 con sus cuatro dientes y mango de 60 pulgadas, además de la forma en que se transportará y almacenará. El mango desmontable facilita la logística, pero debe asegurarse correctamente antes de entrar a línea. Inspeccione dientes, remaches, unión y mango antes de cada uso; una pieza floja o un diente deformado altera la trayectoria de la herramienta. Evite golpear roca oculta y retire residuos después de la jornada para detectar desgaste. El mantenimiento debe conservar la integridad de dientes y fijaciones, no modificar la geometría publicada. Integre la herramienta al EPP forestal y al plan táctico de la brigada, sin usar su especificación USDA como certificación del usuario.'], idealPara: ['Es adecuado para mover sotobosque y rastrillar una línea con cuatro dientes triangulares.', 'Puede emplearse cuando se necesita un mango desmontable de 60 pulgadas para logística de cuadrilla.', 'Sirve para trabajo forestal donde no se requiere la hoja de hacha de una Pulaski.'], aConsiderar: ['Antes de entrar a línea, asegure el mango desmontable y revise que los remaches no tengan holgura.', 'Si hay roca oculta o dientes deformados, suspenda el uso hasta revisar la herramienta.', 'No interprete la especificación USDA publicada como sustituto de capacitación o EPP forestal.'], faqs: [{ q: '¿Cuántos dientes tiene el rastrillo?', a: 'Council Tool publica cuatro dientes triangulares de acero.' }, { q: '¿Cuál es su especificación USDA?', a: 'La ficha del modelo indica USDA Forest Service 5100-284C.' }, { q: '¿El mango es desmontable?', a: 'Sí. Council Tool publica un mango desmontable para LW12-60.' }] },
  'council-tool-fire-swatter-fs15': { seleccion: ['FS15 FSS es el batefuegos Council Tool con pala de caucho masticado de 12 × 15 pulgadas, estructura de acero y mango de fresno de 60 pulgadas. Su función es sofocar llama superficial mediante remate, por lo que se diferencia de una McLeod o Pulaski destinadas a remover combustible y suelo. Tampoco equivale a la bomba Indian, que aplica agua desde una mochila. La pala flexible permite trabajar sobre combustibles superficiales bajo condiciones controladas, pero no define cuándo es seguro atacar un frente ni sustituye el mando operativo. El comprador debe considerar esta referencia como herramienta manual de remate dentro de una táctica autorizada.', 'Pida la clave FS15 FSS y confirme tamaño de pala, longitud de mango y condiciones de almacenamiento para evitar que el caucho se deforme. Antes de cada uso, revise pala, férula, estructura y mango; una unión floja o un caucho roto reduce el control y exige retiro de servicio. No golpee rocas, metal u otros objetos rígidos porque el diseño no está publicado para ese impacto. Use EPP forestal y mantenga rutas de escape, comunicaciones y separación de otros operadores conforme al procedimiento de la brigada. Después de trabajar, elimine residuos y evalúe la pala por cortes, endurecimiento o desprendimientos.'], idealPara: ['Es adecuado para remate de llama superficial dentro de una operación forestal controlada.', 'Puede utilizarse cuando la brigada necesita una pala de caucho en un mango de 60 pulgadas.', 'Sirve como complemento de herramientas de línea que retiran combustible o trabajan suelo.'], aConsiderar: ['Si la propagación está fuera de control, no dependa de este batefuegos como única medida de ataque.', 'Antes de usarlo, revise la férula y la pala de caucho por cortes o desprendimientos.', 'No golpee objetos rígidos porque pueden dañar la pala y comprometer el control de la maniobra.'], faqs: [{ q: '¿De qué material es la pala?', a: 'Council Tool publica una pala de caucho masticado.' }, { q: '¿Qué longitud tiene el mango?', a: 'La ficha publica un mango de fresno de 60 pulgadas.' }, { q: '¿Para qué trabajo se selecciona?', a: 'Se selecciona para sofocar llama superficial y realizar remate manual.' }] },
  'truper-mcleod-mac-17891': { seleccion: ['MAC 17891 es la herramienta McLeod de Truper con cabeza de acero, azadón de filo templado y rastrillo, publicada para limpieza de grandes áreas y líneas corta fuego. Frente a la MT48 FSS de Council Tool, la cotización debe identificar esta clave mexicana y sus dimensiones específicas: mango de madera de 48 pulgadas o 120 cm, azadón de 22 cm y rastrillo de 25 cm. No es una Pulaski, por lo que no debe pedirse si la operación requiere una hoja de hacha para corte. El diseño dos en uno busca alternar remoción de ramaje, rastrillado y trabajo de línea.', 'Al comprar, solicite expresamente código 17891 y verifique la longitud publicada, porque el nombre McLeod por sí solo no identifica configuración ni medida. Considere funda para el filo templado, espacio de transporte y EPP forestal compatible con la jornada. Antes de operar, examine mango de madera, cabeza, unión y borde del azadón; retire una herramienta con grietas, holgura o daño de filo. La limpieza después del uso debe permitir revisar residuos que oculten desgaste, sin afilar o modificar la herramienta fuera del mantenimiento autorizado. Mantenga la zona de trabajo libre de otros brigadistas dentro del arco de uso y transporte el filo protegido.'], idealPara: ['Es adecuada para limpiar grandes áreas y abrir líneas corta fuego con rastrillo y azadón.', 'Puede emplearse para remover ramaje cuando un filo templado forma parte de la tarea.', 'Sirve para brigadas que requieren confirmar una McLeod Truper mediante la clave 17891.'], aConsiderar: ['Al cotizar, pida la clave 17891 para no confundir este modelo con otra herramienta McLeod.', 'Si el mango de madera tiene grietas o la cabeza está floja, retire la herramienta de servicio.', 'Durante el transporte, proteja el filo templado y evite que quede expuesto al personal.'], faqs: [{ q: '¿Cuál es el código del modelo?', a: 'Truper publica el código 17891 para esta McLeod.' }, { q: '¿Qué longitud tiene publicada?', a: 'La ficha indica mango de 48 pulgadas, equivalente a 120 cm.' }, { q: '¿Qué funciones integra?', a: 'Integra un azadón y un rastrillo para trabajo de línea.' }] },
  'indian-90g-fp200': { seleccion: ['Indian 90G con FP200 es la bomba de mochila para brigadas que requieren llevar agua y aplicar chorro recto o abanico desde un tanque de acero galvanizado de cinco galones. Se diferencia de las herramientas Council Tool y Truper porque no corta, rastrilla ni bate combustible: incorpora una bomba manual FP200 de dos cilindros de latón, salida de latón con filtro y boquilla regulable. Indian publica 12.5 lb para la unidad, pero la planificación debe considerar la carga del tanque lleno y la capacidad física del usuario. Es un equipo de apoyo hídrico para una operación definida, no una garantía de control del incendio.', 'Pida el modelo 179014-1 con bomba FP200 y confirme qué boquilla, correa y condiciones de recarga estarán disponibles. Antes de asignarlo, evalúe peso en servicio, acceso a agua y método para mantener el tanque sin contaminación. Inspeccione tapa, abertura de cuatro pulgadas, filtro, conexiones de latón, manguera y bomba; no transporte una unidad con fuga o una correa que no sostenga la carga. Pruebe el patrón de chorro y abanico dentro del procedimiento de mantenimiento antes de enviarla a operación. Después de usarla, vacíe y limpie conforme a las indicaciones del fabricante, revise sellos y documente cualquier pérdida de presión o daño.'], idealPara: ['Es adecuada para una brigada que dispone de recarga de agua y requiere llevarla a puntos forestales.', 'Puede emplearse cuando se necesita elegir entre patrón de chorro recto y patrón de abanico.', 'Sirve como apoyo hídrico portátil, separado de las herramientas para línea y remate.'], aConsiderar: ['Antes de asignarla, calcule el peso de operación con el tanque lleno y la capacidad del usuario.', 'No transporte la bomba si tapa, filtro, manguera o conexiones presentan fuga.', 'Después de cada jornada, limpie la unidad y revise sellos, bomba y presión antes de guardarla.'], faqs: [{ q: '¿Qué capacidad tiene el tanque?', a: 'Indian publica una capacidad de cinco galones.' }, { q: '¿Qué bomba incorpora?', a: 'La referencia incluye una FP200 de dos cilindros de latón.' }, { q: '¿Qué patrón de descarga permite?', a: 'La boquilla publicada permite ajustar de chorro recto a abanico.' }] },
};

const enriquecimientoR11bMarcas: Record<string, Partial<Product>> = {
  'naffco-np-2-5l-dcp': { seleccion: ['NP 2.5L DCP es el extintor portátil NAFFCO de polvo químico seco ABC con capacidad publicada de 2.5 lb y clasificación UL 1-A:10-B:C. Para riesgos A, B y C cubiertos por esa clasificación, se diferencia de K-Guard de Ansul porque éste se destina a grasas y aceites de cocina con agente líquido y rating 2-A:K. NAFFCO publica cilindro de acero, presión de trabajo de 195 psi, tiempo de descarga de diez segundos, alcance de 3.4 m y temperatura de operación de -40 a 49 °C. La selección debe provenir de la evaluación de riesgos y de la clasificación necesaria, no de la capacidad por sí sola.', 'Al comprar, confirme etiqueta, clasificación y agente del modelo entregado, además de soporte, señalización y ubicación que requiera el inmueble. No lo especifique para aceites de cocina ni donde el residuo de polvo sea incompatible con equipos sensibles. El comprador debe integrar inspección mensual, mantenimiento y recarga dentro del programa aplicable, con responsable y evidencia de servicio. Antes de colocarlo en servicio, revise manómetro, sello, pasador, manguera, cilindro y etiqueta; retire cualquier unidad con daño, pérdida de presión o evidencia de descarga. Tras utilizarlo, debe atenderse el evento y enviar el equipo a servicio conforme al programa autorizado.'], idealPara: ['Es adecuado para riesgos A, B y C que correspondan a su clasificación UL 1-A:10-B:C.', 'Puede usarse cuando se requiere un extintor portátil ABC de capacidad publicada de 2.5 lb.', 'Sirve para proyectos que confirmarán soporte, señalización y mantenimiento dentro de su programa de seguridad.'], aConsiderar: ['Si el riesgo principal son grasas o aceites de cocina, seleccione un equipo destinado expresamente a fuego de cocina.', 'Antes de recibir la partida, confirme que la etiqueta del cilindro corresponda a la clasificación UL publicada.', 'No instale una unidad con manómetro fuera de rango, sello roto, cilindro dañado o evidencia de descarga.'], faqs: [{ q: '¿Qué agente contiene este extintor?', a: 'NAFFCO publica polvo químico seco ABC para NP 2.5L.' }, { q: '¿Qué clasificación tiene publicada?', a: 'La ficha publica clasificación UL 1-A:10-B:C.' }, { q: '¿Cuál es su alcance publicado?', a: 'NAFFCO publica un alcance de 3.4 m.' }] },
  'ansul-r-102': { seleccion: ['R-102 es el sistema preingenierizado Ansul para supresión de incendios en equipos y ventilación de cocinas comerciales. Protege campanas, ductos, plénums, filtros y equipos cuando el diseño define boquillas específicas por aparato o cobertura solapada. Se diferencia de K-Guard porque el extintor portátil complementa la respuesta manual, mientras R-102 es un sistema fijo diseñado alrededor de la disposición real de la cocina. Ansul publica agente ANSULEX Low pH Liquid Agent y referencias a UL 300, NFPA 17A y NFPA 96, además de listado UL y ULC y marcado CE. Ninguna de esas referencias sustituye levantar equipos, dimensiones y ventilación en el sitio.', 'Al solicitarlo, entregue plano actualizado, lista de cada aparato, campana, ducto, plénum y cambios previstos de menú o instalación. Pida el diseño de boquillas y cobertura para la configuración efectiva, no una cotización genérica por metros de campana. La inspección debe verificar cilindro, tubería, boquillas, fusibles o actuadores y que los aparatos continúen en la disposición aprobada; una reconfiguración exige revisar el diseño. Mantenga libres las boquillas y coordine el mantenimiento con limpieza de campana, sin desconectar o alterar componentes para facilitar la operación diaria. El programa de servicio debe seguir las instrucciones de Ansul y las obligaciones aplicables al sistema instalado.'], idealPara: ['Es adecuado para una cocina comercial con campana, ductos y equipos definidos en planos.', 'Puede configurarse cuando el diseño requiere boquillas específicas o cobertura solapada publicada.', 'Sirve para proyectos que mantendrán control de cambios sobre la disposición de equipos de cocción.'], aConsiderar: ['Antes de cotizar, entregue la lista y ubicación de cada aparato cubierto por la campana.', 'Si se mueve o reemplaza un equipo de cocción, solicite revisión del diseño y las boquillas.', 'No permita que la limpieza o la operación diaria obstruyan, desconecten o reorienten componentes del sistema.'], faqs: [{ q: '¿Qué agente utiliza R-102?', a: 'Ansul publica ANSULEX Low pH Liquid Agent.' }, { q: '¿Qué áreas protege el sistema?', a: 'El diseño cubre ventilación y equipos definidos para la cocina comercial.' }, { q: '¿Qué debe ocurrir si cambia la cocina?', a: 'La configuración debe revisarse porque boquillas y cobertura dependen de los equipos instalados.' }] },
  'ansul-k-guard': { seleccion: ['K-Guard es el extintor portátil recargable Ansul para grasas y aceites de cocina comercial, con ANSULEX Low pH Liquid Agent y clasificación UL/ULC 2-A:K. Su patrón de descarga ancho y suave lo distingue de un extintor ABC como NP 2.5L: no debe intercambiarse la selección de agentes cuando el peligro corresponde a aceite de cocción. También se diferencia de R-102, que es un sistema fijo para campana, ducto y equipos; K-Guard funciona como equipo portátil complementario, no como sustitución de esa protección cuando el diseño la exige. La compra debe partir de una evaluación de la cocina y del acceso del usuario al punto de riesgo.', 'Pida la configuración comercial disponible para el sitio, con gabinete o soporte, señalización y programa de mantenimiento. Confirme que el punto de instalación permita acercarse sin cruzar una zona insegura y que el personal conozca el plan de respuesta. Antes de ponerlo en servicio, revise etiqueta, manómetro, pasador, sello, manguera y condición general del cilindro. La inspección periódica y la recarga deben realizarse dentro del programa aplicable; después de una descarga, el equipo no debe volver a colgarse como disponible hasta recibir servicio. No lo use para sustituir el levantamiento y mantenimiento del R-102 en una cocina que requiera sistema fijo.'], idealPara: ['Es adecuado para una cocina comercial con riesgo de grasas y aceites de cocción.', 'Puede instalarse como complemento portátil de un sistema fijo diseñado para la campana.', 'Sirve para proyectos que requieren un extintor con clasificación UL/ULC 2-A:K publicada.'], aConsiderar: ['Si la cocina requiere cobertura de campana y ducto, no sustituya el sistema fijo por este extintor portátil.', 'Antes de instalarlo, confirme que el acceso no obligue al usuario a cruzar la zona de fuego.', 'Después de cualquier descarga, envíe el extintor a servicio antes de declararlo nuevamente disponible.'], faqs: [{ q: '¿Para qué tipo de fuego está destinado?', a: 'Ansul lo destina a grasas y aceites de cocina comercial.' }, { q: '¿Qué clasificación publica?', a: 'La ficha publica clasificación UL/ULC 2-A:K.' }, { q: '¿Sustituye un sistema R-102?', a: 'No. R-102 es un sistema fijo y K-Guard es un equipo portátil complementario.' }] },
  'rosenbauer-heros-titan': { seleccion: ['HEROS Titan es el casco Rosenbauer cuya publicación reúne certificaciones EN para combate estructural, incendio forestal y rescate técnico: EN 443, EN 16471 y EN 16473, además de ISO 16073. Esa combinación lo distingue de HEROS H10, que se publica para usos forestales y técnicos con menor peso aproximado, y de los cascos certificados bajo NFPA disponibles en el catálogo. No debe declararse como casco NFPA. Rosenbauer publica carcasa tipo B/3b, pantalla conforme a EN 14458, ajuste exterior con perilla, tallas de 49 a 67 y resistencia de -40 a 300 °C.', 'Al cotizar, defina misión, talla, pantalla, adaptador de máscara y accesorios que realmente requiere la corporación. Pida una prueba de ajuste con máscara y equipo de protección para comprobar interfaz, retención y visión, pues la talla no garantiza compatibilidad operativa. Antes de cada uso inspeccione carcasa, sistema de retención, suspensión, visor y adaptadores; retire el casco después de impacto severo o si aparecen grietas, deformación o componentes que no aseguren. La limpieza y sustitución de piezas deben seguir las indicaciones de Rosenbauer. Mantenga registros de inspección y no agregue accesorios que cambien la configuración certificada del modelo.'], idealPara: ['Es adecuado para una corporación que especifica combate estructural bajo EN 443.', 'Puede seleccionarse para incendio forestal bajo EN 16471 y rescate técnico bajo EN 16473.', 'Sirve cuando se requiere probar ajuste con máscara mediante el adaptador publicado por Rosenbauer.'], aConsiderar: ['Si el pliego exige NFPA, este casco no debe declararse conforme porque Rosenbauer publica certificaciones EN.', 'Antes de comprar, pruebe talla, retención, visor y adaptador con la máscara que utilizará el usuario.', 'Retire de servicio un casco con impacto severo, carcasa agrietada o sistema de retención defectuoso.'], faqs: [{ q: '¿Qué tallas cubre HEROS Titan?', a: 'Rosenbauer publica tallas de 49 a 67.' }, { q: '¿Qué norma aplica a rescate técnico?', a: 'Rosenbauer publica EN 16473 para rescate técnico.' }, { q: '¿Es un casco certificado NFPA?', a: 'No. La ficha del modelo publica certificaciones EN e ISO, no NFPA.' }] },
  'rosenbauer-heros-h10': { seleccion: ['HEROS H10 es el casco ligero Rosenbauer para incendio forestal y rescate técnico, con configuraciones que también refieren usos de altura o agua según la certificación correspondiente. Frente a HEROS Titan, se publica con peso aproximado de 800 g y no con la certificación EN 443 para combate estructural; por ello el comprador debe separar la misión forestal o técnica de cualquier requisito estructural. Rosenbauer publica EN 16471, EN 16473, EN 12492, EN 1385 e ISO 16073-5, talla de 48 a 67, ajuste exterior con perilla, visor integrado según configuración y adaptador de accesorios. No debe declararse como casco NFPA.', 'La cotización debe identificar versión, visor, ventilación, accesorios y misión prevista, pues no toda configuración resuelve las mismas necesidades. Pruebe la talla con protección auditiva, ocular o respiratoria que realmente usará la cuadrilla y verifique que los accesorios solicitados sean los publicados para el casco. Antes de cada salida inspeccione carcasa, retención, perilla, visor y adaptadores; sustituya el equipo tras impacto severo o cuando el fabricante y el programa de inspección lo indiquen. Limpie y mantenga los componentes conforme a Rosenbauer, sin perforar la carcasa ni instalar accesorios no autorizados. Registre la inspección para conservar trazabilidad de cada casco asignado.'], idealPara: ['Es adecuado para incendio forestal cuando el pliego acepta la certificación EN 16471 publicada.', 'Puede seleccionarse para rescate técnico bajo EN 16473 y configuraciones previstas por Rosenbauer.', 'Sirve para cuadrillas que buscan un casco de peso aproximado de 800 g y talla de 48 a 67.'], aConsiderar: ['Si el requisito contractual es NFPA o combate estructural EN 443, no especifique HEROS H10 para esa función.', 'Antes de ordenar, confirme visor, ventilación y accesorios de la configuración que necesita la cuadrilla.', 'Sustituya el casco después de impacto severo y no instale accesorios que no estén autorizados por Rosenbauer.'], faqs: [{ q: '¿Cuál es el peso publicado?', a: 'Rosenbauer publica un peso aproximado de 800 g.' }, { q: '¿Qué tallas cubre el modelo?', a: 'La ficha publica tallas de 48 a 67.' }, { q: '¿Está publicado para combate estructural EN 443?', a: 'No. Las normas publicadas corresponden a usos forestales, técnicos y otras configuraciones indicadas.' }] },
};

const complementoSeleccionR11a: Record<string, string> = {
  'kidde-p9050-fotoelectrico': 'Para comprar P9050, confirme que la aplicación es residencial, que existe un punto de montaje adecuado y que el alcance de la alarma local satisface el plan del inmueble. La batería de 9 V debe llegar identificada dentro de la partida y el responsable debe registrar prueba, limpieza y sustitución conforme al manual. Inspeccione carcasa, botón Test/Hush, cámara y etiqueta antes de instalarla. Si hay daño, contaminación o falla de prueba, reemplácela; no intente convertirla en detector de panel mediante accesorios no publicados.',
  'kidde-kn-cope-d-humo-co': 'Al seleccionar KN-COPE-D, defina los puntos que necesitan ambos tipos de alerta y no suponga que una sola unidad cubre todos los niveles del edificio. Pida el modelo con su batería y valide que la puerta frontal cierre correctamente. Pruebe alarma, voz y estado de batería según el manual, y conserve el registro de la memoria de CO como información de operación, no como diagnóstico del sitio. Limpie e inspeccione carcasa y aberturas; sustituya la unidad si falla la prueba o llega al fin de vida indicado.',
  'kidde-20sar-vrf-interconectable': 'La compra debe listar cada alarma compatible, su alimentación y la ubicación que integrará a la red inalámbrica. Confirme el límite publicado de hasta doce unidades compatibles sin usarlo para justificar cobertura o distribución. Después de la instalación pruebe que una activación alcance a las demás alarmas previstas y registre el resultado. Inspeccione alimentación cableada, respaldo AA, indicador y comunicación después de cualquier cambio de ubicación. Si una unidad no comunica, corrija la configuración conforme a Kidde en vez de asumir que la alarma local mantiene la red operativa.',
  'kidde-p4010acsaq-wf': 'Antes de pedir P4010ACSAQ-WF, confirme alimentación de 120 V, versión, red Wi-Fi y necesidad real de monitor de calidad de aire interior. La batería sellada es respaldo, no autorización para ignorar la alimentación AC requerida por las funciones Wi-Fi. Pruebe interconexión, avisos y estado de la alarma después de instalarla, y documente el responsable que atenderá cualquier alerta remota. Revise carcasa, etiqueta UL 217, conexiones y fecha de reemplazo. Si se modifica la red eléctrica o inalámbrica, valide otra vez la operación publicada antes de depender de avisos.',
  'zoll-aed-plus': 'Al comprar AED Plus, separe explícitamente el DEA, CPR-D-padz, baterías, gabinete y accesorios pediátricos para evitar que una cotización base parezca un programa listo. Confirme la modalidad automática o semiautomática y el idioma de la unidad entregada. El responsable debe revisar estado, autoprueba, fecha de baterías y fecha de pads antes de que algún consumible venza. Inspeccione gabinete, carcasa, electrodos y sellos durante las rondas programadas. Después de un evento, reponga consumibles y documente el uso; Real CPR Help no sustituye capacitación, activación de emergencias ni revisión clínica posterior.',
  'zoll-aed-3': 'La compra de AED 3 debe especificar modalidad, conectividad Wi-Fi si procede, idioma, electrodos y gabinete, además de la necesidad de uso pediátrico. Verifique que la organización tenga responsable para gestionar avisos de conectividad, pues ésta no reemplaza inspección física. En cada revisión compruebe pantalla, estado operativo, consumibles, estuche y fecha de vencimiento. Tras una descarga o caída, active el procedimiento de evaluación y reposición. La pantalla táctil y RapidShock Analysis apoyan al usuario, pero el programa debe mantener capacitación, llamada a emergencias y registro de mantenimiento.',
  'philips-heartstart-frx': 'Antes de adquirir FRx, confirme si la respuesta pediátrica requiere la llave opcional y solicítela como componente separado cuando corresponda. Revise que el cartucho SMART Pads II, batería y estuche cotizados coincidan con la referencia 861304. El responsable debe inspeccionar indicadores de preparación, vencimientos y condición del gabinete según el manual. Después de un uso, los pads y cualquier consumible aplicado se sustituyen dentro del programa. Las instrucciones de voz y el metrónomo facilitan la respuesta, pero no modifican el protocolo médico ni dispensan capacitación y coordinación con servicios de emergencia.',
  'mindray-beneheart-c1a': 'Al cotizar BeneHeart C1A, defina si necesita versión semiautomática, modo infantil, estuche, pads y conectividad gestionada. La unidad publica RescueNet 2.0 como opción, por lo que no debe incluirse sin confirmar la configuración. Programe inspección de batería, electrodos, estado del equipo y fecha de consumibles, además de la prueba que establezca el fabricante. Si ocurre una descarga o alerta, reponga los componentes usados y registre el incidente. La guía ResQNavi y el metrónomo ayudan a la operación, pero la organización conserva responsabilidad sobre capacitación, emergencia y mantenimiento.',
  'zoll-powerheart-g5': 'La solicitud de Powerheart G5 debe confirmar configuración, electrodos adultos o pediátricos, gabinete y responsable del programa. La energía variable y la guía de RCP son funciones del equipo; no determinan que cualquier persona esté entrenada ni que el sitio tenga plan de emergencia. Revise indicador de preparación, batería, pads, carcasa y estuche dentro de la frecuencia indicada por el fabricante. Si la unidad informa falla, vence un consumible o se utiliza en un evento, aplique reemplazo y evaluación antes de devolverla a servicio. Mantenga registro de inspección para que la disponibilidad no dependa de una revisión informal.',
  'lion-battalion-tri-cert': 'Al comprar Battalion, solicite talla, ancho y configuración que permita probarla con pantalón y calcetín de operación. La etiqueta debe corresponder a las aplicaciones publicadas por Lion y no autoriza cambios no aprobados en puntera, plantilla o suela. Antes de asignarla, inspeccione cuero, costuras, tiradores, herrajes, suela y Lock-Fit. Después de exposición, limpieza o daño, revise también la protección Pierce-Protect y retire la bota si su condición compromete el uso. El mantenimiento debe respetar las instrucciones del fabricante y el programa de EPP, con trazabilidad de cada par.',
  'lion-hellfire-felt': 'Para Hellfire, confirme talla, ancho y el tipo de operación estructural antes de incorporar la bota a una dotación. Pida prueba con la interfaz de pantalón y revise que la configuración entregada corresponda a la etiqueta publicada. Inspeccione cuero, forro, costuras, suela y elementos de cierre antes de cada asignación. Tras exposición o limpieza, evalúe daños que justifiquen retiro o servicio conforme a Lion. No modifique la bota con piezas ajenas al fabricante; una reparación no autorizada puede cambiar la condición evaluada del equipo de protección.',
  'lion-primus-guantes': 'La compra debe definir talla, mano dominante y compatibilidad con la manga y el equipo respiratorio que usará el bombero. Solicite la etiqueta del modelo y compruebe que la configuración recibida corresponda a la aplicación estructural publicada. Antes de entrar a servicio, revise costuras, barreras, palma, forro y sistema de cierre. Después de exposición, limpieza o contaminación, inspeccione el guante y retire cualquier par con perforación, pérdida de integridad o ajuste deficiente. Siga el método de cuidado de Lion y mantenga pares asignados para evitar mezclar tallas o condiciones distintas.',
  'msa-globe-guard-hood': 'Al pedir Globe Guard, confirme talla, interfaz con casco, máscara y cuello del conjunto estructural. La capucha debe cubrir conforme a su diseño, pero no reemplaza verificar que no existan huecos entre los demás componentes. Antes de cada uso, revise tejido, costuras, elasticidad y contaminación visible; después de un evento, aplique limpieza e inspección conforme al programa de EPP. No modifique la prenda ni combine piezas que alteren la interfaz prevista. Mantenga registro de asignación y condición para decidir retiro cuando haya daño o no se conserve el ajuste adecuado.',
  'council-tool-fe6-36': 'Al cotizar FE6-36, confirme peso, longitud y procedimiento de uso de la brigada, pues se trata de una herramienta de corte manual. Pida funda o método de transporte seguro y verifique que el mango y la cabeza recibidos correspondan a la referencia. Antes de usar, inspeccione filo, unión, mango y cualquier señal de holgura o grieta. Mantenga distancia de otros operadores y proteja el borde durante traslado. Si se detecta deformación, daño del mango o pérdida de fijación, retire la herramienta hasta evaluación autorizada.',
  'council-tool-hal1p30': 'La compra de HAL1P30 debe especificar referencia, longitud y el tipo de trabajo para el que se incorporará la herramienta. No use su presencia para sustituir un análisis de acceso, fuerza de trabajo o protección del operador. Antes de cada asignación revise cabeza, mango, unión y zonas de agarre; las grietas o holguras requieren retiro de servicio. Tras cada jornada, retire residuos y proteja el equipo durante almacenamiento. El programa de mantenimiento debe conservar la condición del componente sin modificaciones que cambien el diseño publicado por Council Tool.',
  'drager-hps-7000': 'Antes de comprar HPS 7000, defina talla, visor, accesorios y compatibilidad con máscara, protección auditiva y sistema de comunicación. Solicite una prueba de ajuste con el conjunto de EPP real, no sólo una medición de perímetro. En la inspección revise carcasa, suspensión, retención, visor y adaptadores, y retire el casco tras impacto severo o daño visible. La limpieza y los repuestos deben seguir las indicaciones de Dräger para conservar la configuración. Documente revisiones y sustituciones para que el casco asignado mantenga trazabilidad durante toda su vida útil.',
};

