for (const producto of featuredProducts) {
  const ficha = enriquecimientoTrajes[producto.slug]
    ?? enriquecimientoR9Lote2[producto.slug]
    ?? enriquecimientoR9Lote2Rescate[producto.slug]
    ?? enriquecimientoR9Lote2Drones[producto.slug]
    ?? enriquecimientoR9Lote3Scba[producto.slug]
    ?? enriquecimientoR9Lote3Cascos[producto.slug]
    ?? enriquecimientoR9Lote6[producto.slug]
    ?? enriquecimientoR11bRescate[producto.slug]
    ?? enriquecimientoR11bForestal[producto.slug]
    ?? enriquecimientoR11bMarcas[producto.slug]
    ?? enriquecimientoR11a[producto.slug]
    ?? SISTEMAS_CI_REVISADOS[producto.slug];
  if (ficha) Object.assign(producto, ficha);
  const tituloCorregido = TITULOS_SISTEMAS_CI_CORREGIDOS[producto.slug];
  if (tituloCorregido) producto.title = tituloCorregido;
  if (producto.category === 'Sistemas CI' && producto.fuentes) {
    producto.fuentes = producto.fuentes.filter((fuente) => !fuente.url.includes('dof.gob.mx'));
  }
  const detalle = detalleSeleccionPorModelo[producto.slug];
  if (detalle && producto.seleccion) producto.seleccion.push(detalle);
  const complemento = complementoSeleccionR9Lote3[producto.slug];
  if (complemento && producto.seleccion) producto.seleccion.push(complemento);
  const complementoLote6 = complementoSeleccionR9Lote6[producto.slug];
  if (complementoLote6 && producto.seleccion) producto.seleccion.push(complementoLote6);
  const complementoR11a = complementoSeleccionR11a[producto.slug];
  if (complementoR11a && producto.seleccion) producto.seleccion.push(complementoR11a);
}

